elapsed=time.monotonic()-t0
rss=int(p.stdout.split('CHILD_RSS_KIB')[-1].strip())
checks['full_capture_rss_le_40_mib'] = rss <= 40960
checks['full_capture_handoff_deadline'] = elapsed <= 1.0
